<?php
namespace App\Http\Controllers;
use App\Models\{User,Apprentice,TutorGroup,TrainingSession,TimetableChangeBatch as Batch,RegisterFollowupCase as CaseRecord};
use App\Support\{TimetableChanges as Changes,RegisterActions as Actions,RegisterFollowup,LearningAccess};
use Illuminate\Http\Request;
use Illuminate\Pagination\LengthAwarePaginator;
use Illuminate\Support\Facades\DB;
class SessionOperationsController extends Controller {
 private function manager(Request $r):void {abort_unless(LearningAccess::manager($r->user()),403);}
 private function staff(Request $r):void {abort_unless($r->user()->active&&(LearningAccess::manager($r->user())||$r->user()->role==='tutor'),403);}
 private function view(string $v,array $data=[]) {return response()->view('session-operations.'.$v,$data)->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');}
 private function filtered(Request $r):array {$this->staff($r);$d=$r->validate(['from'=>['nullable','date_format:Y-m-d'],'to'=>['nullable','date_format:Y-m-d','after_or_equal:from'],'group'=>['nullable','integer','min:1'],'view'=>['nullable','in:all,needs-register,checks,not-ended,recorded,cancelled'],'search'=>['nullable','string','max:100'],'page'=>['nullable','integer','min:1']]);$from=$d['from']??today()->subDays(30)->toDateString();$to=$d['to']??today()->addDays(90)->toDateString();abort_if(\Carbon\Carbon::parse($from)->diffInDays($to,true)>366,422,'Use a date window of at most366 days.');$manager=LearningAccess::manager($r->user());$groups=TutorGroup::when(!$manager,fn($q)=>$q->where('tutor_id',$r->user()->id))->orderBy('name')->get();if(isset($d['group'])){abort_unless($groups->contains('id',(int)$d['group']),404);}$q=TrainingSession::whereIn('tutor_group_id',$groups->pluck('id'))->whereDate('session_date','>=',$from)->whereDate('session_date','<=',$to)->when($d['group']??null,fn($q,$id)=>$q->where('tutor_group_id',$id));$search=trim($d['search']??'');if($search!==''){$n='%'.str_replace(['!','%','_'],['!!','!%','!_'],mb_strtolower($search)).'%';$q->whereRaw("LOWER(name) LIKE ? ESCAPE '!'",[$n]);}$sessions=$q->orderBy('session_date')->orderBy('start_time')->orderBy('id')->limit(1001)->get();abort_if($sessions->count()>1000,422,'Narrow filters to at most1,000 saved sessions.');$rows=[];$counts=array_fill_keys(RegisterFollowup::VIEWS,0);
  foreach($sessions as$s){if(!Actions::allowed($r->user(),$s)){continue;}$check=Actions::check($s);$bucket=$check['readiness']['bucket'];$counts['all']++;$counts[$bucket]++;if(($d['view']??'all')!=='all'&&$d['view']!==$bucket){continue;}$saved=RegisterFollowup::roster($s);$current=Apprentice::where('tutor_group_id',$s->tutor_group_id)->orderBy('id')->pluck('id')->all();$old=$saved['ids'];sort($old);$candidate=['group_id'=>$s->tutor_group_id,'tutor_id'=>$s->group?->tutor_id,'date'=>$s->session_date->toDateString(),'start'=>$s->start_time,'end'=>$s->end_time,'members'=>$old];$teacher=$s->group?->tutor_id?User::find($s->group->tutor_id):null;$rows[]=['session'=>$s,'scope_check'=>!$teacher||$teacher->role!=='tutor'||!Actions::allowed($teacher,$s),'check'=>$check,'roster_changed'=>$old!==$current,'conflict'=>$s->state==='Planned'&&(bool)Changes::conflicts($candidate,[$s->id]),'case'=>CaseRecord::where('training_session_id',$s->id)->first()];}return compact('rows','counts','groups','from','to','d','manager');
 }
 public function calendar(Request $r) {$result=$this->filtered($r);$page=(int)$r->input('page',1);$result['pageRows']=new LengthAwarePaginator(array_slice($result['rows'],($page-1)*25,25),count($result['rows']),25,$page,['path'=>$r->url(),'query'=>$r->except('page')]);return $this->view('calendar',$result);}
 public function export(Request $r) {$result=$this->filtered($r);return response()->json(['from'=>$result['from'],'to'=>$result['to'],'counts_before_view_filter'=>$result['counts'],'rows'=>array_map(fn($row)=>['session_id'=>$row['session']->id,'group_id'=>$row['session']->tutor_group_id,'date'=>$row['session']->session_date->toDateString(),'start'=>$row['session']->start_time,'end'=>$row['session']->end_time,'state'=>$row['session']->state,'register'=>$row['check']['readiness']['bucket'],'missing_codes'=>$row['check']['readiness']['missing_codes'],'roster_needs_check'=>$row['roster_changed'],'register_access_needs_check'=>$row['scope_check'],'possible_timetable_conflict'=>$row['conflict']],$result['rows']),'learner_names_comments_and_case_notes_exported'=>false,'automatic_marks_or_otj_created'=>false],200,['Content-Disposition'=>'attachment; filename="GTA-Session-Operations.json"','Cache-Control'=>'no-store, private','Referrer-Policy'=>'no-referrer']);}
 public function batches(Request $r) {$this->manager($r);$r->validate(['page'=>['nullable','integer','min:1']]);return $this->view('batches',['batches'=>Batch::orderByDesc('created_at')->orderByDesc('id')->paginate(20)]);}
 public function form(Request $r) {$this->manager($r);$r->validate(['group'=>['nullable','integer','min:1']]);$groups=TutorGroup::orderBy('name')->get();$group=(int)$r->input('group',$groups->first()?->id??0);$sessions=TrainingSession::where('tutor_group_id',$group)->whereDate('session_date','>=',today())->where('state','Planned')->orderBy('session_date')->orderBy('id')->paginate(50)->withQueryString();return $this->view('form',compact('groups','group','sessions'));}
 public function prepare(Request $r) {$this->manager($r);$d=$r->validate(['request_token'=>['required','uuid'],'mode'=>['required','in:move,roster,cancel'],'group_id'=>['required','integer','min:1'],'sessions'=>['required','array','min:1','max:50'],'sessions.*'=>['integer','min:1','distinct'],'shift_days'=>['required','integer','between:-365,365'],'reason'=>['required','string','max:2000'],'confirmed'=>['accepted']]);$b=Changes::prepare($r->user(),(int)$r->session()->get('auth_version'),$d['request_token'],$d['mode'],(int)$d['group_id'],array_map('intval',$d['sessions']),(int)$d['shift_days'],$d['reason']);return to_route('session-changes.show',$b)->with('status','Exact future-session preview saved. No date/roster/attendance changed; another manager must check and apply.');}
 public function show(Request $r,Batch $batch) {$this->manager($r);abort_unless(Changes::intact($batch),409,'Preview evidence needs checking.');return $this->view('show',['batch'=>$batch,'source'=>$batch->source,'fresh'=>Changes::fresh($batch),'applied'=>Changes::applied($batch),'events'=>DB::table('timetable_change_events')->where('batch_id',$batch->id)->orderBy('id')->get(['event','actor_id','created_at'])]);}
 public function decide(Request $r,Batch $batch) {$this->manager($r);$d=$r->validate(['version'=>['required','integer','min:1'],'decision'=>['required','in:apply,reject,withdraw'],'note'=>['required','string','max:2000'],'confirmed'=>['accepted']]);Changes::decide($r->user(),(int)$r->session()->get('auth_version'),$batch,(int)$d['version'],$d['decision'],$d['note']);return back()->with('status','Checked timetable decision saved. No marks/OTJ or profile/group assignments inferred.');}
 public function report(Request $r,Batch $batch) {$this->manager($r);abort_unless(Changes::intact($batch),409);return response()->json(['batch_id'=>$batch->id,'state'=>$batch->state,'mode'=>$batch->mode,'historical_application_verified'=>Changes::applied($batch),'group_id'=>$batch->tutor_group_id,'rows'=>array_map(fn($row)=>collect($row)->only(['id','version','old_date','date','start','end','changed'])->all(),$batch->source['rows']),'private_names_notes_and_rosters_exported'=>false,'external_messages_sent'=>false,'production_approved'=>false],200,['Content-Disposition'=>'attachment; filename="GTA-Checked-Timetable.json"','Cache-Control'=>'no-store, private','Referrer-Policy'=>'no-referrer']);}
 private function caseData(Request $r):array {return $r->validate(['version'=>['required','integer','min:0'],'source_hash'=>['required','regex:/^[a-f0-9]{64}$/D'],'owner_id'=>['required','integer','min:1'],'due_on'=>['required','date_format:Y-m-d','after_or_equal:today'],'note'=>['required','string','max:2000'],'confirmed'=>['accepted']]);}
 public function caseForm(Request $r,TrainingSession $session) {$this->staff($r);abort_unless(Actions::allowed($r->user(),$session),403);$case=CaseRecord::where('training_session_id',$session->id)->first();if($case){abort_unless(Actions::caseAllowed($r->user(),$case,$session),403);}return $this->caseView($r,$session,$case);}
 private function caseView(Request $r,TrainingSession $s,?CaseRecord $case) {abort_if($case&&!Actions::intact($case),409);$check=Actions::check($s);$owners=User::where('active',true)->whereIn('role',['admin','ceo','tutor'])->orderBy('name')->get()->filter(fn($u)=>Actions::allowed($u,$s));return $this->view('case',['session'=>$s,'case'=>$case,'check'=>$check,'details'=>$case?->details,'position'=>$case?Actions::position($case,$s,$check):null,'owners'=>$owners,'events'=>$case?DB::table('register_followup_events')->where('case_id',$case->id)->orderBy('id')->get(['event','actor_id','created_at']):collect()]);}
 public function caseSave(Request $r,TrainingSession $session) {$this->staff($r);abort_unless(Actions::allowed($r->user(),$session),403);$d=$this->caseData($r);$case=CaseRecord::where('training_session_id',$session->id)->first();if($case){abort_unless(Actions::caseAllowed($r->user(),$case,$session),403);}$c=Actions::save($r->user(),(int)$r->session()->get('auth_version'),$session,$case,(int)$d['version'],$d['source_hash'],$d);return to_route('register-actions.show',$session)->with('status','Register follow-up saved/reopened. Attendance and OTJ records were not changed.');}
 public function caseDecide(Request $r,TrainingSession $session) {$this->staff($r);abort_unless(Actions::allowed($r->user(),$session),403);$c=CaseRecord::where('training_session_id',$session->id)->firstOrFail();abort_unless(Actions::caseAllowed($r->user(),$c,$session),403);$d=$r->validate(['version'=>['required','integer','min:1'],'source_hash'=>['required','regex:/^[a-f0-9]{64}$/D'],'decision'=>['required','in:resolve,defer,reopen,withdraw'],'note'=>['required','string','max:2000'],'confirmed'=>['accepted']]);Actions::decide($r->user(),(int)$r->session()->get('auth_version'),$c,(int)$d['version'],$d['source_hash'],$d['decision'],$d['note']);return back()->with('status','Follow-up decision saved; it does not mark anyone present/absent or confirm hours.');}
 public function cases(Request $r) {$this->staff($r);$d=$r->validate(['state'=>['nullable','in:all,Open,Resolved,Deferred,Withdrawn'],'page'=>['nullable','integer','min:1']]);$q=CaseRecord::when(($d['state']??'all')!=='all',fn($q)=>$q->where('state',$d['state']));if(!LearningAccess::manager($r->user())){$q->whereIn('training_session_id',TrainingSession::whereIn('tutor_group_id',TutorGroup::where('tutor_id',$r->user()->id)->select('id'))->pluck('id'));}$raw=$q->orderBy('due_on')->orderBy('id')->limit(1001)->get();abort_if($raw->count()>1000,422,'Narrow stored-state filters to at most1,000 follow-up records.');$rows=[];foreach($raw as$c){$s=TrainingSession::find($c->training_session_id);if($s&&Actions::caseAllowed($r->user(),$c,$s)){$rows[]=['case'=>$c,'session'=>$s,'position'=>Actions::position($c,$s)];}}$page=(int)$r->input('page',1);$rows=new LengthAwarePaginator(array_slice($rows,($page-1)*25,25),count($rows),25,$page,['path'=>$r->url(),'query'=>$r->except('page')]);return $this->view('cases',compact('rows','d'));}
}
